CREATE TABLE v138171 AS SELECT x10.x1, COALESCE(x10.x1, CAST(-7 AS SIGNED)) AS x2, COALESCE(x10.x1, CAST(7 AS UNSIGNED)) AS x3, COALESCE(x10.x1, CAST('2000-01-01' AS DATE)) AS x4, COALESCE(x10.x1, CAST('b' AS CHAR)) AS x5, COALESCE(x10.x1, CAST('2000-01-01' AS DATETIME)) AS x6, COALESCE(x10.x1, CAST('5:4:3' AS TIME)) AS x7, COALESCE(x10.x1, CAST('yet another binary data' AS BINARY)) AS x8, ADDTIME(CAST('1:0:0' AS TIME), CAST('1:0:0' AS TIME)) AS x9 FROM v138052 AS x10